    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_bdim, %ntid.x;

    // Initialize accumulators
    mov.f32 %f_sum, 0f00000000;
    mov.f32 %f_sumsq, 0f00000000;

    // First pass: compute sum and sumsq
    mov.u32 %r_i, %r_tid;
L_LOOP_SUM:
    setp.ge.u32 %p_done, %r_i, %r_M;
