    add.s64 %rd_addr_xi, %rd_x_base, %rd_off_i;
    ld.global.f32 %f_val, [%rd_addr_xi];

    // accumulate
    fma.rn.f32 %f_sumsq, %f_val, %f_val, %f_sumsq;
    add.f32 %f_sum, %f_sum, %f_val;

    add.u32 %r_i, %r_i, %r_bdim;
    bra L_LOOP_SUM;

L_AFTER_SUM:
    // Warp reduction using shfl for sum
    mov.u32 %r_lane, %laneid;

    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 16, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;

    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 8, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;

    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 4, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;

    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 2, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;

    mov.b32 %t0, %f_sum;
    shfl.sync.down.b32 %t0, %t0, 1, 0x1f, 0xffffffff;
    mov.b32 %f_tmp, %t0;
    add.f32 %f_sum, %f_sum, %f_tmp;

    // Warp reduction for sumsq
    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 16, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;

    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 8, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;

    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 4, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;

    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 2, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;

    mov.b32 %t1, %f_sumsq;
    shfl.sync.down.b32 %t1, %t1, 1, 0x1f, 0xffffffff;
    mov.b32 %f_tmp2, %t1;
    add.f32 %f_sumsq, %f_sumsq, %f_tmp2;

    // Store per-warp results to shared memory by lane 0
    mov.u32 %r_tmp, %tid.x;
    shr.u32 %r_warp, %r_tmp, 5;

    cvta.to.shared.u64 %rd_sbase_sum, s_red_sum;
    cvta.to.shared.u64 %rd_sbase_sumsq, s_red_sumsq;

    mul.wide.u32 %rd_off_sh, %r_warp, 4;

    setp.eq.u32 %p_lane0, %r_lane, 0;
    add.s64 %rd_addr_s, %rd_sbase_sum, %rd_off_sh;
    @%p_lane0 st.shared.f32 [%rd_addr_s], %f_sum;
    add.s64 %rd_addr_ss, %rd_sbase_sumsq, %rd_off_sh;
    @%p_lane0 st.shared.f32 [%rd_addr_ss], %f_sumsq;

    // Sync before final reduction
    bar.sync 0;

    // Compute number of warps
    mov.u32 %r_tmp, %ntid.x;
    add.u32 %r_tmp, %r_tmp, 31;
    shr.u32 %r_num_warps, %r_tmp, 5;

    // Final reduction by warp 0
    setp.eq.u32 %p_warp0, %r_warp, 0;
    @!%p_warp0 bra L_SKIP_FINAL_REDUCE;

    setp.lt.u32 %p_take, %r_lane, %r_num_warps;
    @%p_take {
        mul.wide.u32 %rd_off2, %r_lane, 4;
        add.s64 %rd_addr3, %rd_sbase_sum, %rd_off2;
        ld.shared.f32 %f_sum, [%rd_addr3];
        add.s64 %rd_addr4, %rd_sbase_sumsq, %rd_off2;
        ld.shared.f32 %f_sumsq, [%rd_addr4];
    }
    @!%p_take {
        mov.f32 %f_sum, 0f00000000;
        mov.f32 %f_sumsq, 0f00000000;
    }

    // Reduce within warp 0
    mov.b32 %t0, %f_sum;
